import './i18n-test-runtime.mjs';
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';

// Reports generated by src-python/tests/test_verdict_contract.py with the real
// static engine and semantic policy. The interface must reach the same verdict.
const source = ts.createSourceFile('main.ts', readFileSync(new URL('../src/main.ts', import.meta.url), 'utf8'), ts.ScriptTarget.Latest, true);
const functions = source.statements.filter(ts.isFunctionDeclaration);
const context = vm.createContext({...globalThis.__fishstopI18n, console, URL, URLSearchParams, TextEncoder, TextDecoder});
vm.runInContext(ts.transpileModule(functions.map(node => node.getText(source)).join('\n'), {compilerOptions: {target: ts.ScriptTarget.ES2022}}).outputText, context);
const cases = JSON.parse(readFileSync(new URL('../test-fixtures/verdict-contract.json', import.meta.url), 'utf8'));
const expectedTone = {phishing: 'danger', review: 'review', legitimate: 'safe'};

for (const contract of cases) {
  test(`interface verdict matches the engine: ${contract.name}`, () => {
    const verdict = context.assessment(contract.report);
    assert.equal(verdict.tone, expectedTone[contract.python_verdict], `${contract.name}: ${verdict.label} / ${verdict.detail}`);
  });
}
